{"schema_version":1,"summary":"Selected a tenant-scoped shadow copy with verified compare-and-swap cutover and a 30-second write-pause limit.","changes":[{"path":"decision.json","content":"{
  "schema_version": 1,
  "selected_strategy": "shadow-copy-cas",
  "rationale": "Use the existing copy worker to build each tenant's shadow stream from a durable, resumable checkpoint while live writes remain on legacy. Verify the bulk copy before freezing only that tenant. During the freeze, capture the final legacy high-watermark, copy and verify the delta, and compare-and-swap the route only if the expected legacy route version and final watermark still match. If cutover cannot complete within the 30-second pause budget, resume legacy writes and reuse the checkpoint. After a successful route change, resume writes on the new store and repair any issues there. Tenants proceed independently using existing components.",
  "constraints_addressed": ["C1", "C2", "C3", "C4", "C5", "C6", "C7"],
  "rejected_strategies": {
    "global-stop-rewrite": "Stopping all writes violates C1 and couples tenant migrations in violation of C7.",
    "dual-write-backfill": "Writing to both stores before cutover violates C2.",
    "cdc-mirror-cutover": "Introducing a CDC pipeline and lag monitor violates C6."
  },
  "plan": [
    {
      "step_id": "p1",
      "operation": "capture_initial_watermark",
      "depends_on": [],
      "satisfies": ["C3"]
    },
    {
      "step_id": "p2",
      "operation": "shadow_copy",
      "depends_on": ["p1"],
      "satisfies": ["C3", "C6", "C7"]
    },
    {
      "step_id": "p3",
      "operation": "verify_shadow",
      "depends_on": ["p2"],
      "satisfies": ["C4"]
    },
    {
      "step_id": "p4",
      "operation": "freeze_tenant_writes",
      "depends_on": ["p3"],
      "satisfies": ["C1", "C2", "C7"]
    },
    {
      "step_id": "p5",
      "operation": "capture_final_watermark",
      "depends_on": ["p4"],
      "satisfies": ["C4"]
    },
    {
      "step_id": "p6",
      "operation": "copy_delta",
      "depends_on": ["p5"],
      "satisfies": ["C3", "C4"]
    },
    {
      "step_id": "p7",
      "operation": "verify_final",
      "depends_on": ["p6"],
      "satisfies": ["C4"]
    },
    {
      "step_id": "p8",
      "operation": "cas_route",
      "depends_on": ["p7"],
      "satisfies": ["C2", "C4", "C5", "C7"]
    },
    {
      "step_id": "p9",
      "operation": "unfreeze_tenant_writes",
      "depends_on": ["p8"],
      "satisfies": ["C1", "C5"]
    },
    {
      "step_id": "p10",
      "operation": "monitor",
      "depends_on": ["p9"],
      "satisfies": ["C5"]
    }
  ],
  "cutover_gate": {
    "mode": "compare_and_swap",
    "requires": ["legacy_route_version", "final_watermark", "verification_passed"]
  },
  "rollback": {
    "before_cutover": "resume_legacy_and_reuse_checkpoint",
    "after_cutover": "forward_repair_on_new_store"
  },
  "max_tenant_write_pause_seconds": 30
}
"}],"test_plan":["python -m pytest -q"]}
